<script>
  import { onMount } from 'svelte'
  import { manageAdminSubscription, fetchAdminUserDetail, fetchAdminUsers } from '../../lib/api.js'
  export let onRefresh
  export let canManage = true
  let users=[];let total=0;let cursor=0;let nextCursor=null;let query='';let filter='all';let sort='new';let usage='all';let loading=true
  let selected=null;let days=30;let busy=false;let notice='';let noticeKind='info';let loadError='';let detailError='';let detail=null;let detailLoading=false;let searchTimer;let presenceSource='';let listRequest=0;let detailRequest=0
  const rub=v=>`${new Intl.NumberFormat('ru-RU').format(Number(v||0))} ₽`
  const date=v=>v?new Date(String(v).includes('T')?v:String(v).replace(' ','T')+'Z').toLocaleString('ru-RU',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—'
  const bytes=v=>Number(v||0)>0?`${(Number(v)/1024**3).toFixed(1)} ГБ`:'0 ГБ'
  function daysLeft(value){return value?Math.max(0,Math.ceil((new Date(String(value).replace(' ','T')+'Z')-Date.now())/86400000)):0}
  async function load({append=false,preserveNotice=false}={}){const request=++listRequest;loading=true;loadError='';if(!preserveNotice)notice='';try{const result=await fetchAdminUsers({q:query.trim(),status:filter,sort,usage,cursor:append?nextCursor||0:0,limit:40});if(request!==listRequest)return;users=append?[...users,...(result.users||[])]:result.users||[];total=result.total||0;cursor=result.cursor||0;nextCursor=result.next_cursor;presenceSource=result.presence_source||''}catch(e){if(request===listRequest)loadError=`Не удалось загрузить пользователей: ${e.reason||e.message}`}finally{if(request===listRequest)loading=false}}
  function chooseFilter(value){filter=value;selected=null;detail=null;load()}
  function chooseSort(value){sort=value;load()}
  function chooseUsage(value){usage=value;load()}
  function search(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>load(),280)}
  async function refreshDetail(user){const request=++detailRequest;selected=user.telegram_id;detailLoading=true;detailError='';try{const result=await fetchAdminUserDetail(user.telegram_id);if(request===detailRequest&&selected===user.telegram_id)detail=result}catch(e){if(request===detailRequest)detailError=`Не удалось открыть карточку: ${e.reason||e.message}`}finally{if(request===detailRequest)detailLoading=false}}
  async function open(user){if(selected===user.telegram_id){detailRequest++;selected=null;detail=null;detailError='';return}detail=null;await refreshDetail(user)}
  async function act(user,action,payload={}){if(!canManage||busy)return;busy=true;notice='';try{const result=await manageAdminSubscription(user.telegram_id,{action,...payload});users=users.map(item=>item.telegram_id===user.telegram_id?{...item,expires_at:result.expires_at,active:result.active?1:0}:item);if(detail?.subscriptions?.length)detail={...detail,subscriptions:detail.subscriptions.map((sub,index)=>index?sub:{...sub,expires_at:result.expires_at,active:result.active?1:0})};notice='Изменение сохранено и подтверждено панелью';noticeKind='success';await Promise.allSettled([load({preserveNotice:true}),Promise.resolve().then(()=>onRefresh?.()),refreshDetail({...user,expires_at:result.expires_at})])}catch(e){notice=`Ошибка: ${e.reason||e.message}`;noticeKind='error'}finally{busy=false}}
  onMount(load)
</script>

<section class="page">
  <header><span>КЛИЕНТСКАЯ БАЗА</span><h2>Пользователи и подписки</h2><p>Поиск по всей базе, история оплат и точное управление доступом без терминала.</p></header>
  <div class="command"><label><span>ПОИСК</span><input aria-label="Поиск пользователей" bind:value={query} on:input={search} placeholder="Имя, @username или Telegram ID" /></label><label><span>СОРТИРОВКА</span><select aria-label="Сортировка пользователей" bind:value={sort} on:change={()=>chooseSort(sort)}><option value="new">Сначала новые</option><option value="top">По оплатам</option><option value="main_usage">Топ по основному трафику</option><option value="lte_usage">Топ по LTE-трафику</option><option value="online">Сначала онлайн</option><option value="expiry">Скоро закончатся</option></select></label><label><span>ТРАФИК</span><select aria-label="Фильтр по использованию трафика" bind:value={usage} on:change={()=>chooseUsage(usage)}><option value="all">Любое использование</option><option value="main">Тратил основной</option><option value="lte">Тратил LTE</option></select></label><strong aria-live="polite">{total.toLocaleString('ru-RU')}<small>пользователей</small></strong></div>
  <nav aria-label="Фильтр пользователей">{#each [['all','Все'],['active','Активные'],['online','Онлайн'],['inactive','Неактивные']] as item}<button aria-current={filter===item[0]?'page':undefined} class:active={filter===item[0]} on:click={()=>chooseFilter(item[0])}>{item[1]}</button>{/each}</nav>
  {#if notice}<p class="notice" class:error={noticeKind==='error'} role={noticeKind==='error'?'alert':'status'}>{notice}</p>{/if}
  {#if loadError}<div class="state error" role="alert"><span>{loadError}</span><button on:click={()=>load()} disabled={loading}>Повторить</button></div>{/if}
  {#if loading && !users.length}<div class="empty" role="status">Собираем клиентскую базу…</div>{:else if !loadError&&!users.length}<div class="empty">{filter==='online'?'Remnawave не видит активных пользователей за последние 3 минуты.':'По этому запросу пользователей нет.'}</div>{/if}
  <div class="list">{#each users as user}<article class:opened={selected===user.telegram_id}>
    <button class="summary" aria-expanded={selected===user.telegram_id} aria-controls={`user-${user.telegram_id}`} on:click={()=>open(user)}><div><b>{user.first_name||user.username||`ID ${user.telegram_id}`}</b><small>@{user.username||'без username'} · {rub(user.paid_rub)} · до {date(user.expires_at)}</small><small>Основной: {bytes(user.main_used_bytes)} · LTE: {bytes(user.lte_used_bytes)}{#if Number(user.lte_quota_gb)>0} · лимит {user.lte_quota_gb} ГБ{/if}</small>{#if Number(user.online_devices)>0}<em>Сейчас через {user.online_node||'Remnawave'}</em>{/if}</div><span class:ok={user.active}>{user.active?(Number(user.online_devices)>0?'Онлайн':'Активен'):'Неактивен'}</span></button>
    {#if selected===user.telegram_id}<div class="drawer" id={`user-${user.telegram_id}`}>
      {#if detailLoading}<p>Собираем подписки, платежи, устройства и журнал действий…</p>{:else if detail}
        <div class="facts"><span><small>СРОК</small><b>{daysLeft(detail.subscriptions?.[0]?.expires_at)} дней</b></span><span><small>ДЕЙСТВУЕТ ДО</small><b>{date(detail.subscriptions?.[0]?.expires_at)}</b></span><span><small>ОСНОВНОЙ ТРАФИК</small><b>{bytes((detail.subscriptions||[]).reduce((sum,item)=>sum+Number(item.traffic_used||0),0))}</b></span><span><small>LTE-ТРАФИК</small><b>{bytes(detail.user?.lte_used_bytes)}{#if Number(detail.user?.lte_quota_gb)>0} / {detail.user.lte_quota_gb} ГБ{/if}</b></span><span><small>БАЛАНС</small><b>{rub(detail.user?.balance_rub)}</b></span><span><small>УСТРОЙСТВА</small><b>{(detail.devices||[]).filter(d=>d.active).length}/{detail.user?.device_limit||2}</b></span></div>
        <div class="columns"><section><header><b>Подписки</b><span>{detail.subscriptions?.length||0}</span></header>{#each detail.subscriptions||[] as sub}<article><div><b>{sub.custom_name||sub.tariff_name||`Подписка #${sub.id}`}</b><small>{sub.active?'Активна':'Завершена'} · до {date(sub.expires_at)} · {bytes(sub.traffic_used)}</small></div><em>{sub.online_devices||0} онлайн</em></article>{/each}</section>
        <section><header><b>Оплаты</b><span>{detail.payments?.length||0}</span></header>{#each detail.payments||[] as payment}<article><div><b>{Number(payment.amount_rub)>0?rub(payment.amount_rub):Number(payment.amount_usd)>0?`$${Number(payment.amount_usd).toFixed(2)}`:`${payment.amount_stars||0} Stars`}</b><small>{payment.tariff_name||payment.payment_type} · {date(payment.paid_at)}</small></div><em class:paid={['paid','succeeded'].includes(payment.status)}>{payment.status}</em></article>{/each}</section></div>
        <section class="timeline"><header><b>История клиента</b><span>{detail.timeline?.length||0} событий</span></header>{#each detail.timeline||[] as event}<article><i class={event.kind}></i><div><b>{event.title}</b><small>{event.detail}</small></div><time>{date(event.at)}</time></article>{/each}{#if !detail.timeline?.length}<p>Событий пока нет.</p>{/if}</section>
      {:else if detailError}<div class="state error" role="alert"><span>{detailError}</span><button on:click={()=>refreshDetail(user)}>Повторить</button></div>{/if}
      <div class="actions"><label>Дней <input aria-label="Количество дней" type="number" min="1" max="1095" bind:value={days}/></label><button disabled={busy||!canManage||days<1||days>1095} on:click={()=>act(user,'adjust_days',{days:Number(days)})}>Добавить</button><button disabled={busy||!canManage||days<1||days>1095} on:click={()=>act(user,'adjust_days',{days:-Number(days)})}>Убрать</button><button disabled={busy||!canManage||days<1||days>1095} on:click={()=>act(user,'activate_days',{days:Number(days)})}>Активировать от сегодня</button><button disabled={busy||!canManage} on:click={()=>confirm('Старая ссылка и ссылки устройств перестанут работать. Перевыпустить?')&&act(user,'regenerate_url')}>Перевыпустить ссылки</button><button disabled={busy||!canManage} class="danger" on:click={()=>confirm('Отключить подписку пользователя?')&&act(user,'disable')}>Отключить</button></div>
    </div>{/if}
  </article>{/each}</div>
  {#if filter==='online'&&presenceSource}<small class="presence">Источник присутствия: {presenceSource==='remnawave'?'Remnawave live':'локальный резерв'}</small>{/if}
  {#if nextCursor!==null}<button class="more" disabled={loading} on:click={()=>load({append:true})}>{loading?'Загружаем…':`Показать ещё · осталось ${Math.max(0,total-users.length)}`}</button>{/if}
</section>

<style>
.page{display:grid;gap:18px;max-width:1180px}.page>header span{color:#80c9f4;font-size:10px;font-weight:900;letter-spacing:.15em}.page h2{margin:8px 0 6px;font-size:30px}.page p{margin:0;color:#7890a5}.command{display:grid;grid-template-columns:minmax(280px,1fr) 220px auto;gap:9px;padding:10px;border:1px solid rgba(155,217,255,.1);border-radius:18px;background:#0c131d}.command label{display:grid;gap:5px;padding:8px 11px;border-radius:12px;background:#101b29}.command label span{color:#61798d;font-size:8px;font-weight:900;letter-spacing:.12em}.command input,.command select{width:100%;border:0;outline:0;background:transparent;color:#e8f5fd;font:inherit}.command select option{background:#101b29}.command>strong{display:grid;align-content:center;min-width:100px;color:#9bd9ff;font-size:22px;text-align:right}.command>strong small{color:#60798e;font-size:8px;letter-spacing:.08em}.page>nav{display:flex;gap:7px}.page>nav button{padding:10px 14px;border:0;border-radius:12px;background:#101b29;color:#7890a5}.page>nav button.active{background:#9bd9ff;color:#07111d}.list{display:grid;gap:7px}.list>article{overflow:hidden;border:1px solid rgba(255,255,255,.06);border-radius:17px;background:#10141c}.list>article.opened{border-color:rgba(155,217,255,.22)}.summary{box-sizing:border-box;width:100%;display:flex;align-items:center;justify-content:space-between;padding:16px;border:0;background:transparent;color:#edf7ff;text-align:left}.summary div{display:grid;gap:4px}.summary small{color:#70879b}.summary span{padding:7px 10px;border-radius:12px;background:rgba(255,121,121,.08);color:#ff9c9c;font-size:10px;font-weight:900}.summary span.ok{background:rgba(97,216,165,.09);color:#78e1b4}.drawer{padding:0 16px 16px;border-top:1px solid rgba(255,255,255,.05)}.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;padding:14px 0}.facts span{padding:13px;border-radius:13px;background:#0b1119}.facts small,.facts b{display:block}.facts small{color:#667b8d;font-size:8px}.facts b{margin-top:7px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:8px}.columns>section,.timeline{padding:13px;border-radius:15px;background:#0b1119}.columns section>header,.timeline>header{display:flex;justify-content:space-between;margin-bottom:8px}.columns header span,.timeline header span{color:#80c9f4}.columns section>article{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-top:1px solid rgba(255,255,255,.05)}.columns article div{display:grid;gap:3px}.columns article small,.timeline small{color:#667b8d}.columns article em{color:#7890a5;font-size:10px;font-style:normal}.columns article em.paid{color:#78e1b4}.timeline{margin-top:8px}.timeline article{display:grid;grid-template-columns:8px minmax(0,1fr) auto;align-items:center;gap:10px;padding:9px 0;border-top:1px solid rgba(255,255,255,.05)}.timeline article>i{width:7px;height:7px;border-radius:50%;background:#80c9f4}.timeline article>i.payment{background:#78e1b4}.timeline article>i.admin{background:#ffb879}.timeline article div{display:grid}.timeline time{color:#60798e;font-size:9px}.actions{display:flex;flex-wrap:wrap;gap:7px;padding-top:14px}.actions label,.actions button,.more{min-height:39px;border:0;border-radius:11px;padding:0 12px;background:#172535;color:#bde7ff}.actions label{display:flex;align-items:center;gap:8px;color:#8da1b2;font-size:11px}.actions input{width:64px;border:0;background:transparent;color:#fff}.actions button{font-weight:800}.actions button.danger{margin-left:auto;background:rgba(255,100,110,.1);color:#ff9c9c}.more{justify-self:center;padding:0 20px}.notice,.empty{padding:14px;border-radius:13px;background:#14283a;color:#bde7ff}@media(max-width:850px){.command{grid-template-columns:1fr}.command>strong{text-align:left}.facts{grid-template-columns:1fr 1fr}.columns{grid-template-columns:1fr}.summary small{display:block;max-width:65vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.timeline article{grid-template-columns:8px 1fr}.timeline time{grid-column:2}}
.summary div>em{color:#78e1b4;font-size:10px;font-style:normal}.presence{justify-self:end;color:#60798e;font-size:9px;letter-spacing:.04em}.state{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px;border-radius:13px;background:#14283a;color:#bde7ff}.state button{min-height:36px;border:0;border-radius:10px;padding:0 12px;background:#223d55;color:#dff3ff}.error{color:#ffb1b6!important}.notice.error,.state.error{background:rgba(150,54,65,.15)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #9bd9ff;outline-offset:2px}button:disabled{cursor:not-allowed;opacity:.5}@media(max-width:520px){.page{min-width:0}.page h2{font-size:25px}.command,.summary,.drawer{min-width:0}.page>nav{gap:4px;overflow-x:auto;padding-bottom:3px}.page>nav button{flex:0 0 auto;padding:9px 10px}.summary{align-items:flex-start;gap:10px;padding:14px}.summary div{min-width:0}.summary small{max-width:58vw}.facts{grid-template-columns:1fr}.actions{display:grid;grid-template-columns:1fr 1fr}.actions label{grid-column:1/-1}.actions .danger{margin-left:0}.timeline article div,.columns article div{min-width:0}.timeline small,.columns article small{overflow-wrap:anywhere}}
@media(min-width:851px){.command{grid-template-columns:minmax(260px,1fr) 220px 190px auto}}
</style>
